fn nth_prime(n: i64) -> i64 {
    count: i64 = 0;
    candidate: i64 = 2;
    while count < n {
        is_p: i64 = 1;
        d: i64 = 2;
        while (d * d) <= candidate {
            if (candidate % d) == 0 {
                is_p = 0;
            }
            d = d + 1;
        }
        if is_p == 1 {
            count = count + 1;
            if count == n {
                return candidate;
            }
        }
        candidate = candidate + 1;
    }
    return candidate;
}

