}

fn nth_composite(n: i64) -> i64 {
    count: i64 = 0;
    candidate: i64 = 4;
    while count < n {
        is_comp: i64 = 0;
        d: i64 = 2;
        while (d * d) <= candidate {
            if (candidate % d) == 0 {
                is_comp = 1;
                break;
            }
            d = d + 1;
        }
        if is_comp == 1 {
            count = count + 1;
            if count == n {
