}

fn solve(n: i64) -> i64 {
    max_val: i64 = n;
    curr: i64 = n;
    while curr > 1 {
        if (curr % 2) == 0 {
            curr = curr / 2;
        } else {
            curr = (curr * 3) + 1;
        }
        if curr > max_val {
            max_val = curr;
        }
    }
    return max_val;
}

fn nth_palindrome(n: i64) -> i64 {
    count: i64 = 0;
    curr: i64 = 1;
    while count < n {
        is_pal: i64 = 1;
        temp: i64 = curr;
        rev: i64 = 0;
        while temp > 0 {
            digit: i64 = temp % 10;
            rev = rev * 10 + digit;
            temp = temp / 10;
        }
        if rev == curr {
            is_pal = 1;
        } else {
            is_pal = 0;
        }
        if is_pal == 1 {
            count = count + 1;
            if count == n {
                return curr;
            }
        }
        curr = curr + 1;
    }
    return curr;
}

fn nth_abundant(n: i64) -> i64 {
    count: i64 = 0;
    num: i64 = 1;
    while count < n {
        sum: i64 = 0;
        d: i64 = 1;
        while d <= num {
            rem: i64 = num % d;
            if rem == 0 {
                sum = sum + d;
            }
            d = d + 1;
        }
        is_abundant: i64 = 0;
        if sum > (2 * num) {
            is_abundant = 1;
        }
        if is_abundant == 1 {
            count = count + 1;
            if count == n {
                return num;
            }
        }
        num = num + 1;
    }
    return 0;
}

