fn digit_factorial_sum(n: i64) -> i64 {
    // Precompute factorials 0! to 9!
    f0: i64 = 1;
    f1: i64 = 1;
    f2: i64 = 2;
    f3: i64 = 6;
    f4: i64 = 24;
    f5: i64 = 120;
    f6: i64 = 720;
    f7: i64 = 5040;
    f8: i64 = 40320;
    f9: i64 = 362880;

    // Handle edge case n <= 0. 
    // If n is negative, we treat it as 0 (or return 0 depending on interpretation, 
    // but standard digit sum usually implies non-negative or absolute value. 
    // Given examples start at 1, let's assume n >= 0. If n < 0, we take absolute value or return 0.
    // Let's assume input is non-negative as per typical digit problems, but handle 0 explicitly.
    // If n < 0, we can't extract digits with % 10 safely without abs.
    // Let's assume n >= 0 based on examples.

    // Special case for 0
    if n == 0 {
        return f0;
    }

    // Extract digits into an array
    digits: [i64] = [];
    temp: i64 = n;

    // Loop to extract digits
    while temp > 0 {
        rem: i64 = temp % 10;
        digits.push(rem);
        temp = temp / 10;
    }

    // Calculate sum of factorials
    total: i64 = 0;
    for d in digits {
        sum_f: i64 = 0;
        if d == 0 { sum_f = f0; }
        else if d == 1 { sum_f = f1; }
        else if d == 2 { sum_f = f2; }
        else if d == 3 { sum_f = f3; }
        else if d == 4 { sum_f = f4; }
        else if d == 5 { sum_f = f5; }
        else if d == 6 { sum_f = f6; }
        else if d == 7 { sum_f = f7; }
        else if d == 8 { sum_f = f8; }
        else if d == 9 { sum_f = f9; }
        total = total + sum_f;
    }

    return total;
}

